{{ config(materialized='table', schema='HEALTH') }}

-- Source: FED_CMS_MEDICARE_PHYSICIAN_OTHER_PRACTITIONERS_BY_PROVIDER_AND_SERVI (9,781,673 rows)  [row count re-verified against the live table 2026-08-11; header had said 500000]
-- Generated by scripts/gen_mart_models.py
--
-- SUPPRESSED SUBSET, NOT THE WHOLE PICTURE: CMS deletes any row for a service
-- with under 11 Medicare beneficiaries before this file is ever published --
-- the row is gone, not nulled. Live-confirmed 2026-09-20: min(TOT_BENES) = 11,
-- zero rows below it, zero nulls, across all 9,781,673 rows. Any sum, count or
-- "top N" off this table is a FLOOR. One sampled real provider showed 90.2% of
-- their total billing invisible at this NPI x HCPCS x place-of-service grain,
-- versus their own row in health__fed_cms_medicare_physician_other_practitioners_by_provider.
-- Use that provider-level mart for a provider's true total; use this one only
-- for service-mix detail, and say "at least" in front of any number it produces.
-- Fixed 2026-09-20: AVG_MDCR_ALOWD_AMT / _PYMT_AMT / _STDZD_AMT were bare
-- try_to_double() -- a landmine, not an active bug today (live-checked: 0 of
-- 9,781,673 rows hold the literal string 'nan'; 9,771,763 rows genuinely carry
-- real cents, which try_to_double already keeps exact, unlike try_to_number
-- which would round them). No staging model exists for this source (only the
-- sibling by_provider table has one, and it does not cover this NPI x HCPCS x
-- place-of-service grain), so this stays on source() -- wrapped all three
-- casts with stg_float.

with source as (
    select * from {{ source('ripple_raw', 'FED_CMS_MEDICARE_PHYSICIAN_OTHER_PRACTITIONERS_BY_PROVIDER_AND_SERVI') }}
),
provider as (
    select rndrng_npi, tot_mdcr_pymt_amt
    from {{ ref('health__fed_cms_medicare_physician_other_practitioners_by_provider') }}
),

-- visible rows are the service rows CMS published; the remainder row below adds what CMS deleted
with_lock as (
select
    source.RNDRNG_NPI as rndrng_npi,
    RNDRNG_PRVDR_LAST_ORG_NAME as rndrng_prvdr_last_org_name,
    RNDRNG_PRVDR_FIRST_NAME as rndrng_prvdr_first_name,
    RNDRNG_PRVDR_MI as rndrng_prvdr_mi,
    RNDRNG_PRVDR_CRDNTLS as rndrng_prvdr_crdntls,
    RNDRNG_PRVDR_ENT_CD as rndrng_prvdr_ent_cd,
    RNDRNG_PRVDR_ST1 as rndrng_prvdr_st1,
    RNDRNG_PRVDR_ST2 as rndrng_prvdr_st2,
    RNDRNG_PRVDR_CITY as rndrng_prvdr_city,
    RNDRNG_PRVDR_STATE_ABRVTN as rndrng_prvdr_state_abrvtn,
    RNDRNG_PRVDR_STATE_FIPS as rndrng_prvdr_state_fips,
    RNDRNG_PRVDR_ZIP5 as rndrng_prvdr_zip5,
    RNDRNG_PRVDR_RUCA as rndrng_prvdr_ruca,
    RNDRNG_PRVDR_RUCA_DESC as rndrng_prvdr_ruca_desc,
    nullif(trim(RNDRNG_PRVDR_CNTRY), '') as rndrng_prvdr_cntry,
    RNDRNG_PRVDR_TYPE as rndrng_prvdr_type,
    RNDRNG_PRVDR_MDCR_PRTCPTG_IND as rndrng_prvdr_mdcr_prtcptg_ind,
    HCPCS_CD as hcpcs_cd,
    HCPCS_DESC as hcpcs_desc,
    HCPCS_DRUG_IND as hcpcs_drug_ind,
    PLACE_OF_SRVC as place_of_srvc,
    TOT_BENES as tot_benes,
    TOT_SRVCS as tot_srvcs,
    TOT_BENE_DAY_SRVCS as tot_bene_day_srvcs,
    AVG_SBMTD_CHRG as avg_sbmtd_chrg,
    {{ stg_float('AVG_MDCR_ALOWD_AMT') }} as avg_mdcr_alowd_amt,
    {{ stg_float('AVG_MDCR_PYMT_AMT') }} as avg_mdcr_pymt_amt,
    {{ stg_float('AVG_MDCR_STDZD_AMT') }} as avg_mdcr_stdzd_amt,
    -- THE LOCK (2026-09-21). CMS deletes every service row under 11 patients, so the rows here
    -- never add up to the provider. These three columns put the gap on every row, so a sum
    -- off this table carries its own warning instead of relying on someone reading the header.
    --   est_mdcr_pymt_amt           this row's Medicare payment: average payment x services
    --   provider_tot_mdcr_pymt_amt  the provider's true total, from the one-row-per-NPI mart
    --   service_rows_cover_pct       share of that true total the surviving rows account for
    {{ stg_float('AVG_MDCR_PYMT_AMT') }} * {{ stg_float('TOT_SRVCS') }} as est_mdcr_pymt_amt,
    provider.tot_mdcr_pymt_amt as provider_tot_mdcr_pymt_amt,
    round(100 * sum({{ stg_float('AVG_MDCR_PYMT_AMT') }} * {{ stg_float('TOT_SRVCS') }}) over (partition by source.RNDRNG_NPI)
          / nullif(provider.tot_mdcr_pymt_amt, 0), 1) as service_rows_cover_pct
from source
left join provider on provider.rndrng_npi = source.RNDRNG_NPI
),

-- THE LOCK, part two (2026-09-21, Chris said yes): one HIDDEN SERVICES row per provider, HCPCS_CD
-- '_SUPPRESSED', holding the money CMS deleted for services under 11 patients. With it, a plain
-- sum(est_mdcr_pymt_amt) off this table equals the provider mart. Filter hcpcs_cd <> '_SUPPRESSED'
-- to see only real service lines. Counts on the remainder row are null: CMS never says how many.
remainder as (
    select
        rndrng_npi, max(rndrng_prvdr_last_org_name) as rndrng_prvdr_last_org_name, max(rndrng_prvdr_first_name) as rndrng_prvdr_first_name, max(rndrng_prvdr_mi) as rndrng_prvdr_mi, max(rndrng_prvdr_crdntls) as rndrng_prvdr_crdntls,
        max(rndrng_prvdr_ent_cd) as rndrng_prvdr_ent_cd, max(rndrng_prvdr_st1) as rndrng_prvdr_st1, max(rndrng_prvdr_st2) as rndrng_prvdr_st2, max(rndrng_prvdr_city) as rndrng_prvdr_city, max(rndrng_prvdr_state_abrvtn) as rndrng_prvdr_state_abrvtn,
        max(rndrng_prvdr_state_fips) as rndrng_prvdr_state_fips, max(rndrng_prvdr_zip5) as rndrng_prvdr_zip5, max(rndrng_prvdr_ruca) as rndrng_prvdr_ruca, max(rndrng_prvdr_ruca_desc) as rndrng_prvdr_ruca_desc, max(rndrng_prvdr_cntry) as rndrng_prvdr_cntry,
        max(rndrng_prvdr_type) as rndrng_prvdr_type, max(rndrng_prvdr_mdcr_prtcptg_ind) as rndrng_prvdr_mdcr_prtcptg_ind,
        '_SUPPRESSED' as hcpcs_cd,
        'Services CMS deleted before publishing: under 11 patients each. Payment is the provider total minus the visible rows.' as hcpcs_desc,
        null as hcpcs_drug_ind, '_' as place_of_srvc,
        null as tot_benes, null as tot_srvcs, null as tot_bene_day_srvcs,
        null as avg_sbmtd_chrg, null as avg_mdcr_alowd_amt, null as avg_mdcr_pymt_amt, null as avg_mdcr_stdzd_amt,
        max(provider_tot_mdcr_pymt_amt) - sum(est_mdcr_pymt_amt) as est_mdcr_pymt_amt,
        max(provider_tot_mdcr_pymt_amt) as provider_tot_mdcr_pymt_amt,
        max(service_rows_cover_pct) as service_rows_cover_pct
    from with_lock
    group by rndrng_npi
    having max(provider_tot_mdcr_pymt_amt) - sum(est_mdcr_pymt_amt) > 0.005
),

-- Providers with NO surviving service row at all: 89,266 in the 2026-09-20 audit. They exist only in the
-- provider mart. One row each, so the table's total equals the provider mart's total, not only per NPI.
absent as (
    select
        p.rndrng_npi, p.rndrng_prvdr_last_org_name, p.rndrng_prvdr_first_name, p.rndrng_prvdr_mi, p.rndrng_prvdr_crdntls, p.rndrng_prvdr_ent_cd, p.rndrng_prvdr_st1, p.rndrng_prvdr_st2, p.rndrng_prvdr_city, p.rndrng_prvdr_state_abrvtn, p.rndrng_prvdr_state_fips, p.rndrng_prvdr_zip5, p.rndrng_prvdr_ruca, p.rndrng_prvdr_ruca_desc, p.rndrng_prvdr_cntry, p.rndrng_prvdr_type, p.rndrng_prvdr_mdcr_prtcptg_ind,
        '_SUPPRESSED' as hcpcs_cd,
        'Every service this provider billed had under 11 patients; CMS published none of them.' as hcpcs_desc,
        null as hcpcs_drug_ind, '_' as place_of_srvc,
        null as tot_benes, null as tot_srvcs, null as tot_bene_day_srvcs,
        null as avg_sbmtd_chrg, null as avg_mdcr_alowd_amt, null as avg_mdcr_pymt_amt, null as avg_mdcr_stdzd_amt,
        p.tot_mdcr_pymt_amt as est_mdcr_pymt_amt,
        p.tot_mdcr_pymt_amt as provider_tot_mdcr_pymt_amt,
        0.0 as service_rows_cover_pct
    from {{ ref('health__fed_cms_medicare_physician_other_practitioners_by_provider') }} p
    where not exists (select 1 from source s where s.RNDRNG_NPI = p.rndrng_npi)
      and p.tot_mdcr_pymt_amt > 0.005
)

select * from with_lock
union all
select * from remainder
union all
select * from absent
